CREATE CACHED TABLE AGENCE(ID_AGENCE INTEGER GENERATED BY DEFAULT AS IDENTITY(START WITH 0) NOT NULL PRIMARY KEY,NOM VARCHAR(100) NOT NULL,ADRESSE VARCHAR(250),VILLE VARCHAR(100));
CREATE CACHED TABLE PROPRIETAIRE(ID_PROPRIO INTEGER GENERATED BY DEFAULT AS IDENTITY(START WITH 0) NOT NULL PRIMARY KEY,NOM VARCHAR(50) NOT NULL,PRENOM VARCHAR(50) NOT NULL,TEL VARCHAR(20),ADRESSE VARCHAR(250));
CREATE CACHED TABLE ENTREPRENEUR(ID_ENTREPRENEUR INTEGER GENERATED BY DEFAULT AS IDENTITY(START WITH 0) NOT NULL PRIMARY KEY,NOM_SOCIETE VARCHAR(100) NOT NULL,METIER VARCHAR(50),TEL VARCHAR(20));
CREATE CACHED TABLE LOCATAIRE(ID_LOCATAIRE INTEGER GENERATED BY DEFAULT AS IDENTITY(START WITH 0) NOT NULL PRIMARY KEY,NOM VARCHAR(50) NOT NULL,PRENOM VARCHAR(50) NOT NULL,TEL VARCHAR(20),SOLDE_COMPTE DECIMAL(7,2));
CREATE CACHED TABLE PERSONNEL(ID_PERSONNEL INTEGER GENERATED BY DEFAULT AS IDENTITY(START WITH 0) NOT NULL PRIMARY KEY,NOM VARCHAR(50) NOT NULL,PRENOM VARCHAR(50) NOT NULL,ID_AGENCE INTEGER NOT NULL,CONSTRAINT SYS_FK_72 FOREIGN KEY(ID_AGENCE) REFERENCES AGENCE(ID_AGENCE));
CREATE CACHED TABLE BIEN(ID_BIEN INTEGER GENERATED BY DEFAULT AS IDENTITY(START WITH 0) NOT NULL PRIMARY KEY,ADRESSE VARCHAR(250),CP INTEGER,VILLE VARCHAR(100),SURFACE DECIMAL(5,2),LOYER_HC DECIMAL(7,2),CHARGES DECIMAL(7,2),TYPE_MANDAT VARCHAR(10),ID_PROPRIO INTEGER NOT NULL,ID_AGENCE INTEGER NOT NULL,ID_PERSONNEL_GESTIONNAIRE INTEGER,CONSTRAINT SYS_FK_89 FOREIGN KEY(ID_PROPRIO) REFERENCES PROPRIETAIRE(ID_PROPRIO),CONSTRAINT SYS_FK_90 FOREIGN KEY(ID_AGENCE) REFERENCES AGENCE(ID_AGENCE),CONSTRAINT SYS_FK_91 FOREIGN KEY(ID_PERSONNEL_GESTIONNAIRE) REFERENCES PERSONNEL(ID_PERSONNEL));
CREATE CACHED TABLE CONTRAT_BAIL(ID_BAIL INTEGER GENERATED BY DEFAULT AS IDENTITY(START WITH 0) NOT NULL PRIMARY KEY,DATE_DEBUT DATE NOT NULL,DATE_FIN DATE,ID_BIEN INTEGER NOT NULL,ID_LOCATAIRE INTEGER NOT NULL,ID_AGENCE INTEGER NOT NULL,CONSTRAINT SYS_FK_100 FOREIGN KEY(ID_BIEN) REFERENCES BIEN(ID_BIEN),CONSTRAINT SYS_FK_101 FOREIGN KEY(ID_LOCATAIRE) REFERENCES LOCATAIRE(ID_LOCATAIRE),CONSTRAINT SYS_FK_102 FOREIGN KEY(ID_AGENCE) REFERENCES AGENCE(ID_AGENCE));
CREATE CACHED TABLE FACTURE(ID_FACTURE INTEGER GENERATED BY DEFAULT AS IDENTITY(START WITH 0) NOT NULL PRIMARY KEY,DATE_FACTURE DATE NOT NULL,MONTANT DECIMAL(7,2),OBJET VARCHAR(255),ID_BIEN INTEGER NOT NULL,ID_ENTREPRENEUR INTEGER NOT NULL,CONSTRAINT SYS_FK_111 FOREIGN KEY(ID_BIEN) REFERENCES BIEN(ID_BIEN),CONSTRAINT SYS_FK_112 FOREIGN KEY(ID_ENTREPRENEUR) REFERENCES ENTREPRENEUR(ID_ENTREPRENEUR));
CREATE CACHED TABLE PAIEMENT(ID_PAIEMENT INTEGER GENERATED BY DEFAULT AS IDENTITY(START WITH 0) NOT NULL PRIMARY KEY,DATE DATE NOT NULL,MONTANT DECIMAL(7,2),MOYEN_PAIEMENT VARCHAR(50),ID_BAIL INTEGER NOT NULL,CONSTRAINT SYS_FK_119 FOREIGN KEY(ID_BAIL) REFERENCES CONTRAT_BAIL(ID_BAIL));
